# Generated by joobqui-selfhosted sdk:generate from templates/sdks/elixir/test/joobq/workflow/activities_test.exs.j2. DO NOT EDIT.
defmodule JoobQ.Workflow.ActivitiesTest do
  use ExUnit.Case, async: true

  import JoobQ.Workflow

  alias JoobQ.Workflow.Activities

  defp echo(tag), do: fn input, job -> {:ok, {tag, input, job.step_id}} end

  defp job(payload, checkpoints \\ %{}),
    do: %JoobQ.Job{payload: payload, checkpoints: checkpoints, step_id: "s-1", kind: "activity"}

  test "every step, compensation and update handler is found by its activity name" do
    activities =
      new("shop")
      |> step("reserve", echo(:reserve),
        input: %{sku: input("sku")},
        compensate: compensation(echo(:release))
      )
      |> parallel(fn wf ->
        step(wf, "charge", echo(:charge), input: [output("reserve", "id"), input("sku")])
      end)
      |> wait_for("approval",
        signal: "go",
        compensate: compensation(echo(:undo), input: input("sku"))
      )
      |> timer("pause", for_ms: 1)
      |> update("rename", echo(:rename))
      |> update("peek", result: update_input())
      |> Activities.of()

    assert activities |> Map.keys() |> Enum.sort() == [
             "shop/@update/rename",
             "shop/approval/compensate",
             "shop/charge",
             "shop/reserve",
             "shop/reserve/compensate"
           ]

    job = job(%{"sku" => "A1"}, %{"reserve" => %{"id" => "r-1"}})
    assert activities["shop/reserve"].(job) == {:ok, {:reserve, %{sku: "A1"}, "s-1"}}
    assert activities["shop/charge"].(job) == {:ok, {:charge, ["r-1", "A1"], "s-1"}}

    assert activities["shop/reserve/compensate"].(job) ==
             {:ok, {:release, %{"id" => "r-1"}, "s-1"}}

    assert activities["shop/approval/compensate"].(job) == {:ok, {:undo, "A1", "s-1"}}

    assert activities["shop/@update/rename"].(job(%{"to" => "x"})) ==
             {:ok, {:rename, %{"to" => "x"}, "s-1"}}
  end

  test "a step without an input gets the run's input" do
    activities = new("w") |> step("a", echo(:a)) |> Activities.of()
    assert activities["w/a"].(job(%{"n" => 1})) == {:ok, {:a, %{"n" => 1}, "s-1"}}
  end
end
